  ui_story_5067_50670101_27_dialog_content = "Sabe... Acho que o Aqua Lord também disse algo parecido no passado...",
  ui_story_5067_50670101_28_dialog_content = "Mas a verdadeira questão é, como vou explicar essas exigências aos moradores da cidade?",
  ui_story_5067_50670101_29_dialog_content = "Todos conseguem se lembrar como era o templo...",
