  ui_story_5067_50670101_45_dialog_content = "Vou garantir que todos saibam exatamente como você quer que seu novo templo seja construído.",
  ui_story_5067_50670101_46_dialog_content = "Obrigado, Connolly!",
  ui_story_5067_50670301_1_dialog_content = "Queen Connolly! Tenho assuntos urgentes para discutir com você!",
  ui_story_5067_50670301_2_dialog_content = "Apesar da agenda cheia, não devemos subestimar isso.",
  ui_story_5067_50670301_3_dialog_content = "... Ok! Vou fazer o meu melhor para ouvir!",
