  ui_story_5067_50670301_6_dialog_content = "Manter a dignidade dos amigos é algo que sempre fiz.",
  ui_story_5067_50670301_7_dialog_content = "Entendo... Vamos voltar aos assuntos da cidade então?",
  ui_story_5067_50670301_8_dialog_content = "Sim, Queen Connolly!",
  ui_story_5067_50670301_9_dialog_content = "Primeiro, ainda há um número considerável de soldados tritões rondando perto da cidade. Estou montando uma equipe de batedores para me ajudar a eliminá-los.",
  ui_story_5067_50670301_10_dialog_content = "Eliminar todos eles está se mostrando uma tarefa extremamente difícil.",
  ui_story_5067_50670301_11_dialog_content = "Ah... Isso parece bem frustrante... Mas talvez meus tentáculos possam te ajudar na batalha?",
  ui_story_5067_50670301_12_dialog_content = "Não, Robyn e eu conseguimos lidar com isso muito bem sozinhos. Mais importante...",
  ui_story_5067_50670301_13_dialog_content = "Muitos moradores têm relatado estranhas alucinações, e nós poderíamos usar sua ajuda com isso!",
  ui_story_5067_50670301_14_dialog_content = "Espere, o quê...?",
  ui_story_5067_50670301_15_dialog_content = "Várias coisas estranhas têm acontecido na cidade ultimamente, e muitas pessoas afirmam estar vendo e ouvindo coisas também.",
  ui_story_5067_50670301_16_dialog_content = "Alucinações... Então eles estão vendo e ouvindo coisas que não estão realmente lá...?",
  ui_story_5067_50670301_17_dialog_content = "Exatamente, é estranho. Eles começaram a discutir sobre tesouros invisíveis e eventos que nunca aconteceram.",
