  ui_story_5067_50670301_19_dialog_content = "Como algo assim pode estar acontecendo...?",
  ui_story_5067_50670301_20_dialog_content = "Ainda estamos no processo de reconstrução... Se isso continuar acontecendo, tudo vai desmoronar novamente.",
  ui_story_5067_50670301_21_dialog_content = "E então minha promessa aos Antons e a todos os outros será...",
  ui_story_5067_50670301_22_dialog_content = "Se ao menos o Senhor da Água estivesse aqui para me guiar...",
  ui_story_5067_50670301_23_dialog_content = "Não, essa é minha responsabilidade! Eu preciso encontrar uma resposta sozinho!",
  ui_story_5067_50670301_24_dialog_content = "Parece que você também está sem ideias, né?",
  ui_story_5067_50670301_25_dialog_content = "O Golfinho Branco disse que alguns dos moradores da cidade também são muito conhecedores...",
  ui_story_5067_50670301_26_dialog_content = "Talvez um deles possa me ajudar a resolver esse problema... Você conhece alguém assim?",
  ui_story_5067_50670301_27_dialog_content = "Alguém experiente... Acho que conheço alguém que se encaixa nesse perfil...",
  ui_story_5067_50670301_28_dialog_content = "Uma sábia que já seguiu o lendário herói Istvan. Ela é conhecida como—A Senhora na Chaleira!",
  ui_story_5067_50670301_29_dialog_content = "Há rumores de que ela é imensamente rica e vive reclusa em uma mansão secreta onde um barco está ancorado no mar.",
  ui_story_5067_50670301_30_dialog_content = "Com a sabedoria dela, ela pode ser capaz de apontar a direção certa para você.",
  ui_story_5067_50670301_31_dialog_content = "Obrigado... Muito obrigado, Dayna. Vou pensar em uma maneira de encontrar esse sábio...",
  ui_story_5067_50670301_32_dialog_content = "A Senhora na Chaleira... Certo?",
  ui_story_5067_50670301_33_dialog_content = "Vamos indo!",
  ui_story_5067_50670301_34_dialog_content = "Você poderia usar um conselheiro real, Connolly.",
  ui_story_5067_50670301_35_dialog_content = "Resolver problemas seria muito mais fácil com um.",
  ui_story_5067_50670301_36_dialog_content = "Eu... Eu sei. Eu só preciso ter coragem... para pedir a ela para ser minha orientadora!",
  ui_story_5067_50670501_1_dialog_content = "É... É esse o lugar...?",
  ui_story_5067_50670501_2_dialog_content = "Um... Perdoe-me, mas a Senhora na Chaleira está disponível agora...?",
  ui_story_5067_50670501_3_dialog_content = "Bem bem, se não é a Connolly... A nova rainha da cidade.",
  ui_story_5067_50670501_4_dialog_content = "Deixe-me adivinhar, você se deparou com algum tipo de problema e precisa do meu conselho?",
  ui_story_5067_50670501_5_dialog_content = "Hã...? C-Como você sabia...?",
  ui_story_5067_50670501_6_dialog_content = "Nada que acontece no fundo do mar escapa ao meu conhecimento. Vamos ver...",
  ui_story_5067_50670501_7_dialog_content = "Se seu pedido for digno de consideração!",
  ui_story_5067_50670501_8_dialog_content = "Bem... As pessoas na cidade têm visto e ouvido coisas estranhas ultimamente...",
  ui_story_5067_50670501_9_dialog_content = "Eu queria saber se você poderia me dizer a causa dessas alucinações!",
  ui_story_5067_50670501_10_dialog_content = "Como rainha, preciso encontrar uma maneira de me livrar deles...",
  ui_story_5067_50670501_11_dialog_content = "Caso contrário, isso arruinará nossos esforços de reconstrução e mergulhará a cidade inteira no caos novamente!",
  ui_story_5067_50670501_12_dialog_content = "A história por trás deste assunto é longa e intrincada, e também está inextricavelmente ligada a você.",
  ui_story_5067_50670501_13_dialog_content = "Com certeza você está ciente da história do Senhor Aqua, certo?",
  ui_story_5067_50670501_14_dialog_content = "Ah... B-Bem, o Senhor das Águas estava adormecido por muito tempo e realmente não mencionou nada do seu passado para mim.",
  ui_story_5067_50670501_15_dialog_content = "Heheh, então você não tem ideia. Você sabia que o Senhor da Água já foi conhecido como o deus do medo e da dor?",
  ui_story_5067_50670501_16_dialog_content = "Medo... e dor?!",
  ui_story_5067_50670501_17_dialog_content = "De fato. A terrível aparência do Senhor Aqua forçava os outros a obedecerem por medo, e seu poder absoluto trazia uma dor insuportável a todos que invadiam seu domínio.",
  ui_story_5067_50670501_18_dialog_content = "O Senhor Aqua era uma divindade verdadeiramente perigosa em seu tempo.",
  ui_story_5067_50670501_19_dialog_content = "...",
  ui_story_5067_50670501_20_dialog_content = "Mas... Mas eu nunca pensei que fosse tão assustador assim...",
  ui_story_5067_50670501_21_dialog_content = "Oho? Você pode estar certo. Afinal, um deus não escolhe seu próprio propósito.",
  ui_story_5067_50670501_22_dialog_content = "Sua morte e renascimento, no entanto, inevitavelmente produzem muitos fragmentos de poder.",
  ui_story_5067_50670501_23_dialog_content = "A situação atual não é diferente.",
  ui_story_5067_50670501_24_dialog_content = "É provável que a fonte das alucinações tanto nos habitantes da cidade quanto nos soldados tritões seja o mesmo poder.",
  ui_story_5067_50670501_25_dialog_content = "Embora sejam apenas fragmentos do poder original do Senhor da Água, eles já impactaram a cidade de uma maneira muito significativa.",
  ui_story_5067_50670501_26_dialog_content = "Se for esse o caso, você realmente pretende resolver esse dilema pessoalmente?",
  ui_story_5067_50670501_27_dialog_content = "Claro. É meu dever resolvê-lo como rainha.",
  ui_story_5067_50670501_28_dialog_content = "Eu simplesmente não sei como esses fragmentos de poder afetarão os Antons...",
  ui_story_5067_50670501_29_dialog_content = "Oh... Você está preocupado com aquelas coisinhas?",
  ui_story_5067_50670501_30_dialog_content = "É perfeitamente natural querer os fragmentos do poder do Senhor da Água para si mesmo...",
  ui_story_5067_50670501_31_dialog_content = "Reconstruir um templo de fé deve ser simples o suficiente com esse tipo de poder.",
  ui_story_5067_50670501_32_dialog_content = "Seria bom dar a eles um novo lar o mais rápido possível... mas...",
  ui_story_5067_50670501_33_dialog_content = "Você se preocupa que reconstruir o templo deles restaurará seu poder original... não é?",
  ui_story_5067_50670501_34_dialog_content = "... Você tem medo que eles se tornem símbolos de medo e dor novamente...",
  ui_story_5067_50670501_35_dialog_content = "Bem... É que...",
  ui_story_5067_50670501_36_dialog_content = "Você fica tão fofo(a) quando está preocupado(a)...",
  ui_story_5067_50670501_37_dialog_content = "Mas não se preocupe, minha querida. Você tem muito pouco a temer.",
  ui_story_5067_50670501_38_dialog_content = "À medida que esses pequenos lentamente recuperam seu poder anterior, será que eles ascenderão a um trono de terror...",
  ui_story_5067_50670501_39_dialog_content = "Ou se tornar algo completamente diferente...",
  ui_story_5067_50670501_40_dialog_content = "Tudo depende dos seus pensamentos, Connolly. Afinal, o único que pode controlá-los é você.",
  ui_story_5067_50670501_41_dialog_content = "Meus... pensamentos...?",
  ui_story_5067_50670501_42_dialog_content = "Entendo. Vou... Vou fazer o que acho certo.",
  ui_story_5067_50670501_43_dialog_content = "Eles são meus companheiros importantes, além de protetores desta cidade. Eu... Eu não deveria duvidar deles assim.",
  ui_story_5067_50670501_44_dialog_content = "Muito bem. Agora vá e faça o que você acredita ser certo, e faça com convicção. Estou mais do que disposto a continuar oferecendo meus conselhos também.",
  ui_story_5067_50670501_45_dialog_content = "Quanto ao meu pagamento... Heheh, não se preocupe, minha querida, vou te dar um bom negócio.",
  ui_story_5067_50670601_1_dialog_content = "Ufa... Faz muito tempo que não recebemos relatos de alucinações...",
  ui_story_5067_50670601_2_dialog_content = "Agora que a cidade está em paz novamente, me pergunto como está indo a reconstrução do templo...?",
  ui_story_5067_50670601_3_dialog_content = "Olhe, é Queen Connolly!",
  ui_story_5067_50670601_4_dialog_content = "Nossa cidade está muito mais segura graças à sua proteção! Vida longa à rainha!",
  ui_story_5067_50670601_5_dialog_content = "Viva Queen Connolly, aquele que nos salvou de nossas dolorosas lembranças!",
  ui_story_5067_50670601_6_dialog_content = "Sem a gentil intervenção dela, quem sabe por quanto tempo teríamos sido atormentados por aquelas alucinações...",
  ui_story_5067_50670601_7_dialog_content = "Espere... Espere!",
  ui_story_5067_50670601_8_dialog_content = "Não vocês de novo! O que vocês querem com nossa rainha desta vez?!",
  ui_story_5067_50670601_9_dialog_content = "Por favor, não entenda mal! N-Nós viemos oferecer nossa gratidão a Queen Connolly também!",
  ui_story_5067_50670601_10_dialog_content = "Apesar de nossas constantes tentativas de capturá-la no passado, ela ainda achou adequado nos libertar daquelas alucinações de pesadelo...",
  ui_story_5067_50670601_11_dialog_content = "Vossa Majestade! Se não se importar, também gostaríamos de oferecer nossa ajuda!",
  ui_story_5067_50670601_12_dialog_content = "Se você realmente quer ajudar...",
  ui_story_5067_50670601_13_dialog_content = "Muito bem então! Realmente precisamos de mais algumas mãos para terminar a reconstrução do templo, então vá até lá e veja do que eles precisam!",
  ui_story_5067_50670601_14_dialog_content = "Como quiser, Queen Connolly!",
  ui_story_5067_50670601_15_dialog_content = "Transição",
  ui_story_5067_50670601_16_dialog_content = "Algum tempo depois—",
  ui_story_5067_50670601_17_dialog_content = "Eu declaro que a construção do templo de Queen Connolly... está oficialmente concluída!",
  ui_story_5067_50670601_18_dialog_content = "Vida longa à rainha! Vida longa à rainha!",
  ui_story_5067_50670601_19_dialog_content = "Agora que o Aqua Queen tem um novo templo, nossa cidade pode desfrutar de paz duradoura novamente!",
  ui_story_5067_50670601_20_dialog_content = "Graças à rainha, conseguimos reconstruir nossa casa.",
  ui_story_5067_50670601_21_dialog_content = "Olha! É ela...?",
  ui_story_5067_50670601_22_dialog_content = "Connolly! Connolly! Connolly!",
  ui_story_5067_50670601_23_dialog_content = "Ahhhhh... Ch-Chega, pessoal! Vocês estão me envergonhando...",
  ui_story_5067_50670601_24_dialog_content = "Ufa, finalmente consegui me afastar. Mesmo que não me incomode tanto, todos ainda estão um pouco animados demais...",
  ui_story_5067_50670601_25_dialog_content = "Mas o mais importante...",
  ui_story_5067_50670601_26_dialog_content = "Nossa casa! Nosso novíssimo lar-templo! Hmm-hmm-hmm!",
  ui_story_5067_50670601_27_dialog_content = "Durante todo esse tempo, os Antons não se acalmaram nem um pouco...",
  ui_story_5067_50670601_28_dialog_content = "Eles devem estar tão felizes... Como vocês estão gostando da nova casa, pessoal?",
  ui_story_5067_50670601_29_dialog_content = "Está perfeito, Connolly! Nós te amamos muito!",
  ui_story_5067_50670601_30_dialog_content = "É ainda mais magnífico do que imaginávamos. Obrigado.",
  ui_story_5067_50670601_31_dialog_content = "Nossas memórias estão voltando aos poucos.",
  ui_story_5067_50670601_32_dialog_content = "Hã? Você quer dizer... Você está começando a se lembrar do seu passado?",
  ui_story_5067_50670601_33_dialog_content = "Sim, e muito!",
  ui_story_5067_50670601_34_dialog_content = "Nossa divindade está retornando para nós enquanto falamos.",
  ui_story_5067_50670601_35_dialog_content = "O peso do nosso poder e propósito.",
  ui_story_5067_50670601_36_dialog_content = "O quê?! Quer dizer... É mesmo? Estou tão feliz pelos três...",
  ui_story_5067_50670601_37_dialog_content = "(Mas de acordo com a Senhora na Chaleira...)",
  ui_story_5067_50670601_38_dialog_content = "(Isso significa que um deus do medo e da dor está prestes a renascer?)",
  ui_story_5067_50670601_39_dialog_content = "Se isso acontecer...",
  ui_story_5067_50670601_40_dialog_content = "Não, acredito que um novo deus virá residir neste belo e novo templo.",
  ui_story_5067_50670601_41_dialog_content = "Huh? Essa voz...",
  ui_story_5067_50670601_42_dialog_content = "E este deus terá um novo nome, um que seja cheio de bondade e alegria.",
  ui_story_5067_50670601_43_dialog_content = "Talvez seja... Um deus da música e amizade?",
  ui_story_5067_50670601_44_dialog_content = "É você... o Golfinho Branco...",
  ui_story_5067_50670601_45_dialog_content = "Espere por mim! Estou indo te encontrar!",
  ui_story_5067_50670801_1_dialog_content = "Haa... Haa... Golfinho branco... Eu pensei...",
  ui_story_5067_50670801_2_dialog_content = "Achei que nunca mais ouviria de você.",
  ui_story_5067_50670801_3_dialog_content = "Não se preocupe. Sempre estive bem ao seu lado.",
  ui_story_5067_50670801_4_dialog_content = "Mas, depois de ver o quão bem você se saiu todo esse tempo, achei que isso seria o melhor.",
  ui_story_5067_50670801_5_dialog_content = "Você acha que eu... Me saí bem?",
  ui_story_5067_50670801_6_dialog_content = "Claro. E agora, você e os Antons dominaram o poder de um novo deus.",
  ui_story_5067_50670801_7_dialog_content = "Huh...?!",
  ui_story_5067_50670801_8_dialog_content = "Basta olhar... Você consegue ver peixes em todas as ruas da cidade agora, não é?",
  ui_story_5067_50670801_9_dialog_content = "Na verdade, você deveria até conseguir ver o mundo exterior—",
  ui_story_5067_50670801_10_dialog_content = "I-Isso é incrível! Parece mesmo um sonho!",
  ui_story_5067_50670801_11_dialog_content = "Será que eu poderia estar sonhando agora?",
  ui_story_5067_50670801_12_dialog_content = "Oh? Você finalmente notou?",
  ui_story_5067_50670801_13_dialog_content = "Hã...? Eu sabia...",
  ui_story_5067_50670801_14_dialog_content = "Mas este não é um sonho comum, Connolly.",
  ui_story_5067_50670801_15_dialog_content = "O medo e a dor que o Aqua Lord já incorporou são, na verdade, a fonte do seu poder latente.",
  ui_story_5067_50670801_16_dialog_content = "No passado, você desenvolveu o poder de se conectar com o vazio para evitar a dor e lidar com seus medos.",
  ui_story_5067_50670801_17_dialog_content = "Meu passado... Eu vejo...",
  ui_story_5067_50670801_18_dialog_content = "Naquela época, havia muito medo e dor dos quais eu queria fugir...",
